(function (window) {
  'use strict';

  var Paho = window.Paho || {};

  Paho.MQTT = (function () {
    function Client(host, port, path, clientId) {
      if (typeof path === 'undefined') {
        path = '/mqtt';
      }
      if (typeof clientId === 'undefined') {
        clientId = path;
        path = '/mqtt';
      }
      this.host = host;
      this.port = Number(port);
      this.path = path.startsWith('/') ? path : '/' + path;
      this.clientId = clientId;
      this.connected = false;
      this.socket = null;
      this.onConnectionLost = null;
      this.onMessageArrived = null;
      this.onMessageDelivered = null;
      this._keepAliveInterval = 30000;
      this._pingTimer = null;
    }

    Client.prototype.connect = function (options) {
      options = options || {};
      var self = this;
      var protocol = options.useSSL ? 'wss://' : 'ws://';
      var url = protocol + self.host + ':' + self.port + self.path;

      try {
        self.socket = new WebSocket(url, ['mqttv3.1', 'mqtt']);
      } catch (err) {
        if (options.onFailure) {
          options.onFailure({ errorCode: 7, errorMessage: err.message });
        }
        return;
      }

      self.socket.binaryType = 'arraybuffer';

      var connTimeout = setTimeout(function () {
        if (!self.connected) {
          try { self.socket.close(); } catch (e) {}
          if (options.onFailure) {
            options.onFailure({ errorCode: 1, errorMessage: 'Connection timed out' });
          }
        }
      }, (options.timeout || 10) * 1000);

      self.socket.onopen = function () {
        var cleanSession = typeof options.cleanSession === 'boolean' ? options.cleanSession : true;
        var keepAlive = options.keepAliveInterval || 30;
        self._keepAliveInterval = keepAlive * 1000;

        var vHeader = [0x00, 0x04, 0x4D, 0x51, 0x54, 0x54, 0x04];
        var flags = cleanSession ? 0x02 : 0x00;
        vHeader.push(flags);
        vHeader.push((keepAlive >> 8) & 0xFF);
        vHeader.push(keepAlive & 0xFF);

        var idBytes = [];
        for (var i = 0; i < self.clientId.length; i++) {
          idBytes.push(self.clientId.charCodeAt(i));
        }

        var payload = [(idBytes.length >> 8) & 0xFF, idBytes.length & 0xFF].concat(idBytes);
        var remLen = vHeader.length + payload.length;

        var lenBytes = [];
        do {
          var digit = remLen % 128;
          remLen = Math.floor(remLen / 128);
          if (remLen > 0) digit = digit | 0x80;
          lenBytes.push(digit);
        } while (remLen > 0);

        var packet = new Uint8Array([0x10].concat(lenBytes).concat(vHeader).concat(payload));
        self.socket.send(packet.buffer);
      };

      self.socket.onmessage = function (event) {
        var bytes = new Uint8Array(event.data);
        var type = (bytes[0] >> 4) & 0x0F;

        if (type === 2) {
          clearTimeout(connTimeout);
          var returnCode = bytes[3];
          if (returnCode === 0) {
            self.connected = true;
            self._startPing();
            if (options.onSuccess) {
              options.onSuccess({ invocationContext: options.invocationContext });
            }
          } else {
            self.connected = false;
            if (options.onFailure) {
              options.onFailure({ errorCode: returnCode, errorMessage: 'Connection refused by broker' });
            }
          }
        } else if (type === 3) {
          var idx = 1;
          var multiplier = 1;
          var length = 0;
          var digit;
          do {
            digit = bytes[idx++];
            length += (digit & 127) * multiplier;
            multiplier *= 128;
          } while ((digit & 128) !== 0);

          var topicLen = (bytes[idx] << 8) | bytes[idx + 1];
          idx += 2;
          var topicChars = [];
          for (var t = 0; t < topicLen; t++) {
            topicChars.push(String.fromCharCode(bytes[idx++]));
          }
          var topic = topicChars.join('');

          var payloadChars = [];
          while (idx < bytes.length) {
            payloadChars.push(String.fromCharCode(bytes[idx++]));
          }
          var payloadStr = decodeURIComponent(escape(payloadChars.join('')));

          if (self.onMessageArrived) {
            self.onMessageArrived({
              destinationName: topic,
              payloadString: payloadStr
            });
          }
        }
      };

      self.socket.onclose = function () {
        clearInterval(self._pingTimer);
        self.connected = false;
        if (self.onConnectionLost) {
          self.onConnectionLost({ errorCode: 8, errorMessage: 'Socket closed' });
        }
      };

      self.socket.onerror = function (err) {
        clearInterval(self._pingTimer);
        self.connected = false;
        if (self.onConnectionLost) {
          self.onConnectionLost({ errorCode: 7, errorMessage: 'Socket error' });
        }
      };
    };

    Client.prototype._startPing = function () {
      var self = this;
      clearInterval(self._pingTimer);
      self._pingTimer = setInterval(function () {
        if (self.connected && self.socket && self.socket.readyState === WebSocket.OPEN) {
          self.socket.send(new Uint8Array([0xC0, 0x00]).buffer);
        }
      }, self._keepAliveInterval);
    };

    Client.prototype.subscribe = function (topic, options) {
      if (!this.connected || !this.socket) return;
      options = options || {};
      var topicBytes = [];
      for (var i = 0; i < topic.length; i++) {
        topicBytes.push(topic.charCodeAt(i));
      }
      var packetId = 1;
      var vHeader = [(packetId >> 8) & 0xFF, packetId & 0xFF];
      var payload = [(topicBytes.length >> 8) & 0xFF, topicBytes.length & 0xFF].concat(topicBytes).concat([options.qos || 0]);
      var remLen = vHeader.length + payload.length;

      var lenBytes = [];
      do {
        var digit = remLen % 128;
        remLen = Math.floor(remLen / 128);
        if (remLen > 0) digit = digit | 0x80;
        lenBytes.push(digit);
      } while (remLen > 0);

      var packet = new Uint8Array([0x82].concat(lenBytes).concat(vHeader).concat(payload));
      this.socket.send(packet.buffer);
    };

    Client.prototype.send = function (message) {
      if (!this.connected || !this.socket) return;
      var topicBytes = [];
      for (var i = 0; i < message.destinationName.length; i++) {
        topicBytes.push(message.destinationName.charCodeAt(i));
      }
      var utf8Payload = unescape(encodeURIComponent(message.payloadString));
      var payloadBytes = [];
      for (var p = 0; p < utf8Payload.length; p++) {
        payloadBytes.push(utf8Payload.charCodeAt(p));
      }

      var vHeader = [(topicBytes.length >> 8) & 0xFF, topicBytes.length & 0xFF].concat(topicBytes);
      var remLen = vHeader.length + payloadBytes.length;

      var lenBytes = [];
      do {
        var digit = remLen % 128;
        remLen = Math.floor(remLen / 128);
        if (remLen > 0) digit = digit | 0x80;
        lenBytes.push(digit);
      } while (remLen > 0);

      var packet = new Uint8Array([0x30].concat(lenBytes).concat(vHeader).concat(payloadBytes));
      this.socket.send(packet.buffer);
    };

    Client.prototype.disconnect = function () {
      clearInterval(this._pingTimer);
      if (this.socket && this.socket.readyState === WebSocket.OPEN) {
        this.socket.send(new Uint8Array([0xE0, 0x00]).buffer);
        this.socket.close();
      }
      this.connected = false;
    };

    Client.prototype.isConnected = function () {
      return this.connected;
    };

    function Message(payload) {
      this.payloadString = typeof payload === 'string' ? payload : JSON.stringify(payload);
      this.destinationName = '';
      this.qos = 0;
    }

    return {
      Client: Client,
      Message: Message
    };
  })();

  window.Paho = Paho;
})(typeof window !== 'undefined' ? window : this);
